class Solution:
    def minWindow(self, s: str, t: str) -> str:
        ori, cnt = {}, {}
        for c in t:
            ori[c] = ori.get(c, 0) + 1
        sLen = len(s)
        ansL, ansR = -1, -1
        length = float('inf')

        def check() -> bool:
            for k, v in ori.items():
                if cnt.get(k, 0) < v:
                    return False
            return True

        l = 0
        for r in range(sLen):
            if ori.get(s[r], 0) > 0:
                cnt[s[r]] = cnt.get(s[r], 0) + 1
            while check() and l <= r:
                if r - l + 1 < length:
                    length = r - l + 1
                    ansL, ansR = l, l + length
                if s[l] in ori:
                    cnt[s[l]] -= 1
                l += 1
        if ansL == -1:
            return ""
        return s[ansL:ansR]
